-- 必修一 U1 语法补丁2:12道"成分识别"术语题→12道新应用题(搭配多样,避开已用)。保留原答案位=分布不变(15/15/15/15)。
-- 只 UPDATE 这12行(id键,幂等设固定值)。Aaron 跑。
BEGIN;
UPDATE public.junior_grammar_questions SET stem='"Our school is building ____ this year."', option_a='very modern', option_b='a new library', option_c='quite fast', option_d='open to all', correct_answer='B', explanation='building 后接宾语需名词短语 a new library;very modern/open to all 形容词短语、quite fast 副词短语,不能作宾语。', question_type='mcq' WHERE id='fb08bd1d-4ef0-42d8-a6dd-42351a4da874';
UPDATE public.junior_grammar_questions SET stem='"Our spoken English is getting better ____."', option_a='day by day', option_b='a big step', option_c='very good', option_d='speak more', correct_answer='A', explanation='修饰 is getting better 表方式/程度需副词短语 day by day;a big step 名词短语、very good 形容词短语、speak more 动词短语。', question_type='mcq' WHERE id='3edaada4-872f-472a-bccf-e40e13293ed1';
UPDATE public.junior_grammar_questions SET stem='"Young children are often ____ the world around them."', option_a='a big question', option_b='ask a lot', option_c='very often', option_d='curious about', correct_answer='D', explanation='be curious about 对…好奇,形容词短语作表语;a big question 名词短语、ask a lot 动词短语、very often 副词短语,均不合适。', question_type='mcq' WHERE id='c56d7f96-2a36-4a77-ad3a-140295ada05e';
UPDATE public.junior_grammar_questions SET stem='"____ took part in the charity show."', option_a='Very willingly', option_b='Quite generous', option_c='Many young volunteers', option_d='Glad to help', correct_answer='C', explanation='句子缺主语,需名词短语 Many young volunteers;其余是副词/形容词短语,不能作主语。', question_type='mcq' WHERE id='5f3b4707-6b1b-438c-8ae4-b5d17fbca5d7';
UPDATE public.junior_grammar_questions SET stem='"After the long trip, we were all ____ walking."', option_a='a good rest', option_b='sit down', option_c='quite slowly', option_d='tired of', correct_answer='D', explanation='be tired of 厌倦,形容词短语作表语:be tired of walking;其余不能跟在 were 后接 walking。', question_type='mcq' WHERE id='6d69a0c9-eb16-41ea-b2c5-95727853c1cc';
UPDATE public.junior_grammar_questions SET stem='"The crowd cheered ____ when the team won."', option_a='a great victory', option_b='very excited', option_c='jump up', option_d='loudly and happily', correct_answer='D', explanation='修饰动词 cheered 需副词短语 loudly and happily;a great victory 名词短语、very excited 形容词短语、jump up 动词短语。', question_type='mcq' WHERE id='b8bb1013-b619-45a6-af86-44a80598fafe';
UPDATE public.junior_grammar_questions SET stem='"Good habits bring us ____."', option_a='very slowly', option_b='quite useful', option_c='easy to keep', option_d='a healthy life', correct_answer='D', explanation='bring us 后接直接宾语需名词短语 a healthy life;其余是副词/形容词短语。', question_type='mcq' WHERE id='318746da-780b-449f-bf04-89bd2ea79dbc';
UPDATE public.junior_grammar_questions SET stem='"She explained the new rules ____."', option_a='a clear example', option_b='very clear', option_c='explain again', option_d='very clearly', correct_answer='D', explanation='修饰动词 explained 需副词短语 very clearly;a clear example 名词短语、very clear 形容词短语、explain again 动词短语。', question_type='mcq' WHERE id='896b6b46-19be-41f4-adae-6c3871874020';
UPDATE public.junior_grammar_questions SET stem='"This song is very ____ young people."', option_a='a big hit', option_b='popular with', option_c='sing along', option_d='quite loudly', correct_answer='B', explanation='be popular with 受…欢迎,形容词短语作表语:popular with young people;a big hit 名词短语、sing along 动词短语、quite loudly 副词短语。', question_type='mcq' WHERE id='5f6ab85e-0ac4-46c2-a93c-a605b3c82995';
UPDATE public.junior_grammar_questions SET stem='"The students raised ____ for the poor children."', option_a='very kindly', option_b='quite generous', option_c='a lot of money', option_d='willing to help', correct_answer='C', explanation='raised 后接宾语需名词短语 a lot of money;very kindly 副词短语、quite generous/willing to help 形容词短语。', question_type='mcq' WHERE id='7a5a8004-53fb-4ff8-87bf-2f63291094bc';
UPDATE public.junior_grammar_questions SET stem='"I will never forget ____ in junior high."', option_a='very happily', option_b='my best friends', option_c='quite close', option_d='hard to leave', correct_answer='B', explanation='forget 后接宾语需名词短语 my best friends;其余是副词/形容词短语。', question_type='mcq' WHERE id='ea335529-b0c7-44a3-b1a0-f32ec3af956c';
UPDATE public.junior_grammar_questions SET stem='"Some students feel ____ their exam results."', option_a='a hard test', option_b='worried about', option_c='study harder', option_d='very carefully', correct_answer='B', explanation='feel 是系动词,后接形容词短语 worried about 作表语:worried about their results;其余是名词/动词/副词短语。', question_type='mcq' WHERE id='fbc29fa2-0b1d-46f7-8914-830d215f3161';
COMMIT;
-- 校验:分布应仍 15/15/15/15;术语(中文答案/下列哪一/选出前缀)应=0
SELECT correct_answer, count(*) FROM public.junior_grammar_questions WHERE point_id IN (SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1') GROUP BY correct_answer ORDER BY correct_answer;
SELECT count(*) AS terminology FROM public.junior_grammar_questions WHERE point_id IN (SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1') AND (stem ~ '下列哪一' OR stem ~ '^选出' OR option_a ~ '[一-鿿]' OR option_b ~ '[一-鿿]');
